import {createServer} from 'node:http';
const nodes=[{id:'h0',name:'Mali',level:1,parent:null},{id:'h1',name:'Koulikoro',level:2,parent:'h0'},{id:'h2',name:'Kati',level:3,parent:'h1'},{id:'h3',name:'Aire',level:4,parent:'h2'},{id:'h4',name:'CSCOM',level:5,parent:'h3'},{id:'other',name:'Autre CSCOM',level:5,parent:'h3'},{id:'h5',name:'Site A',level:6,parent:'h4'},{id:'h6',name:'Site B',level:6,parent:'h4'}];
let fail=false;
function unit(n){let path='/'+n.id,p=n.parent;while(p){path='/'+p+path;p=nodes.find(x=>x.id===p)?.parent;}return {...n,parent:n.parent?{id:n.parent}:undefined,path,lastUpdated:n.lastUpdated||'2026-01-01T00:00:00.000'};}
createServer(async(req,res)=>{const url=new URL(req.url,'http://localhost');let body='';for await(const c of req)body+=c;res.setHeader('Content-Type','application/json');if(url.pathname==='/__qa/fail-next'){fail=true;res.end('{}');return;}if(url.pathname.includes('/organisationUnitGroups/')){const id=url.pathname.split('/').at(-1).replace(/\.json$/,'');res.end(JSON.stringify({id,organisationUnits:nodes.filter(n=>id==='EQgJEq5Ga2K'?n.level===3:id==='a8PnG1kmKY9'?n.level===5:n.level===6).map(n=>({id:n.id}))}));return;}if(url.pathname.endsWith('organisationUnitLevels.json')){res.end(JSON.stringify({organisationUnitLevels:[1,2,3,4,5,6].map(level=>({level,name:'Niveau '+level}))}));return;}if(url.pathname.endsWith('organisationUnits.json')){res.end(JSON.stringify({pager:{pageCount:1,total:nodes.length},organisationUnits:nodes.map(unit)}));return;}const id=url.pathname.split('/').at(-1).replace(/\.json$/,'');const n=nodes.find(n=>n.id===id);if(!n){res.statusCode=404;res.end('{}');return;}if(req.method==='PATCH'){const patch=JSON.parse(body);if(patch[0]?.op!=='test'||patch[0]?.value!==n.parent||patch[1]?.op!=='replace'){res.statusCode=409;res.end('{}');return;}n.parent=patch[1].value.id;n.lastUpdated=new Date().toISOString();if(fail){fail=false;res.statusCode=503;res.end('{}');return;}res.end(JSON.stringify({status:'OK'}));return;}res.end(JSON.stringify(unit(n)));}).listen(5400,'0.0.0.0',()=>console.log('DHIS2 fictif prêt.'));
